import {RULES} from './learning-model.js?v=20261102-learning2';
export const METHOD_REVIEWED='2026-11-04';
export const METHOD_CONTENT_REVIEWED='2026-11-05';
export const METHOD_SOURCES=[
 ['Yang et al. (2021)','Testing (quizzing) boosts classroom learning: A systematic and meta-analytic review','https://pubmed.ncbi.nlm.nih.gov/33683913/','Die Metaanalyse von 222 Unterrichtsstudien fand im Mittel bessere Lernleistungen durch Quizzen. Der Vorteil hing unter anderem von Vergleichsbedingung, Prüfungsformat und Korrekturfeedback ab.','Across 222 classroom studies, quizzing improved achievement on average. The benefit varied with factors including the comparison condition, test format and corrective feedback.'],
 ['Latimier, Peyre & Ramus (2021)','A Meta-Analytic Review of the Benefit of Spacing out Retrieval Practice Episodes on Retention','https://doi.org/10.1007/s10648-020-09572-8','Verteiltes Abrufen war im Mittel wirksamer als geballtes Abrufen. Wachsende Abstände waren insgesamt nicht signifikant besser als gleichbleibende; die Studie belegt nicht die konkrete Intervallfolge der App.','Spaced retrieval outperformed massed retrieval on average. Expanding intervals were not significantly better overall than uniform intervals; the study does not establish the app’s particular schedule.'],
 ['Rawson & Dunlosky (2022)','Successive Relearning: An Underexplored but Potent Technique for Obtaining and Maintaining Knowledge','https://www.psychologicalscience.org/journals/current-directions/09637214221100484/','Der Überblick stützt erfolgreiches Abrufen bis zu einem Lernkriterium und erneutes Lernen in späteren Sitzungen.','The review supports retrieval to a learning criterion followed by relearning in later sessions.','https://doi.org/10.1177/09637214221100484'],
 ['Butler & Roediger (2008)','Feedback enhances the positive effects and reduces the negative effects of multiple-choice testing','https://pubmed.ncbi.nlm.nih.gov/18491500/','Nach Multiple-Choice-Fragen erhöhte sofortiges wie verzögertes Korrekturfeedback die richtigen Antworten und verringerte übernommene falsche Auswahlantworten in einem späteren Abruftest gegenüber fehlendem Feedback.','After multiple-choice practice, both immediate and delayed corrective feedback improved correct recall and reduced intrusion of incorrect options on a later cued-recall test compared with no feedback.'],
 ['van den Broek et al. (2023)','Optimizing Multiple-Choice Questions for Retrieval Practice: Delayed Display of Answer Alternatives Enhances Vocabulary Learning','https://research-portal.uu.nl/en/publications/optimizing-multiple-choice-questions-for-retrieval-practice-delay/','Mit vier Sekunden festem Abstand vor den Auswahlantworten war das Behalten von Vokabeln nach mehreren Tagen in drei von vier Experimenten besser als bei sofortiger Anzeige. Das untersuchte Verfahren entspricht nicht dem selbstbestimmten Einblenden der App.','A fixed four-second delay before the options improved vocabulary retention after several days in three of four experiments compared with immediate display. That procedure differs from the app’s learner-paced reveal.','https://doi.org/10.1037/edu0000810'],
 ['Brom et al. (2026)',"Retrieval Practice in the Wild: Comparing Different Multiple-Choice Question Formats on a Children's TV Gaming Site",'https://research-portal.uu.nl/en/publications/retrieval-practice-in-the-wild-comparing-different-multiple-choic/','Auf einer Kinder-Spieleseite führte selbstbestimmtes Einblenden zu einem kleinen Vorteil beim Anteil vollständig abgeschlossener Quizze gegenüber sofortiger Anzeige oder sechs Sekunden fester Wartezeit. Es gab keinen Unterschied im gemessenen kurzfristigen Lernzuwachs; langfristiges Behalten wurde damit nicht belegt.','On a children’s gaming site, learner-paced revealing slightly increased the proportion completing the quiz compared with immediate display or a fixed six-second wait. There was no difference in measured short-term learning gains; this did not establish a long-term retention benefit.','https://doi.org/10.1002/acp.70217'],
 ['Ruitenburg et al. (2026)','A Meta-Analysis of the Effectiveness and Boundary Conditions of Retrieval Practice, Distributed Practice, and Interleaved Practice in Authentic School Classrooms','https://doi.org/10.1007/s10648-026-10225-5','Die Metaanalyse von 53 Studien an Grund- und weiterführenden Schulen fand im Mittel Vorteile für Abruf-, verteiltes und verschachteltes Üben, abhängig von den Bedingungen.','Across 53 primary- and secondary-school studies, retrieval, distributed and interleaved practice showed benefits on average, depending on conditions.']
];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderLearningMethod(english=false){
 const c=(de,en)=>english?en:de,ref=n=>` <a href="#lernmethode/method-source-${n+1}">[${n+1}]<span class="sr"> ${c('Quelle','Source')}: ${esc(METHOD_SOURCES[n][0])}</span></a>`;
 const date=value=>new Date(value).toLocaleDateString(english?'en-GB':'de-DE',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
 const sections=[
 ['goal',c('Was du hier lernst','What you learn'),c('Du übst Vogelnamen und Quick Find Codes, einschließlich hinterlegter Namensvarianten. Fotos verbinden Namen und Vogel; das Bestimmen unbekannter Vogelbilder ist nicht Teil der Übungen.','Practise bird names and Quick Find Codes, including listed name variants. Photos connect names with birds; the exercises do not teach identification of unfamiliar bird photos.')],
 ['daily',c('Deine Tagesrunde','Your daily round'),c(`Bis zu ${RULES.round} Rundenfragen: zuerst fällige Wiederholungen, dann Neues, bei Bedarf ergänzt durch Zusatzversuche. Pro lokalem Kalendertag werden höchstens ${RULES.newPerDay} neue Ziele vorgestellt, über alle Sprachen und Methoden hinweg. Ein Ziel ist etwa der englische Name der Amsel, gefragt auf Deutsch. Neue Ziele werden vor dem Üben vorgestellt. Ein Ziel zählt beim Anzeigen der Vorstellung zum Tagesbudget; ein Methodenwechsel führt ein bekanntes Paar nicht erneut ein.`,`Up to ${RULES.round} round questions: due reviews first, then new targets, plus extra attempts when needed. At most ${RULES.newPerDay} new targets are introduced per local calendar day across all languages and methods. One target might be the English name of the Eurasian Blackbird, prompted in German. New targets are introduced before practice. A target counts towards the daily budget when its introduction is displayed; changing methods does not reintroduce a known pair.`)+`</p><p>`+c('Deine Artenauswahl bestimmt neue Ziele. Fällige Wiederholungen begonnener Ziele bleiben in der gewählten Lernrichtung und Methode unabhängig davon verfügbar.','Your species selection determines new targets. Due reviews of started targets remain available in the selected direction and method regardless of that selection.')+`</p><p>`+c(`„Weiterlernen“ startet bis zu ${RULES.round} Fragen mit deiner Artenauswahl und Antwortmethode, unabhängig von Fragenzahl und Lernstandsfilter eigener Runden. Unter „Weitere Runde selbst zusammenstellen“ wählst du diese selbst. Beide erlauben zusätzliche neue Ziele über das Tageslimit hinaus; ihre Vorstellungen zählen ebenfalls zum verbrauchten Tagesbudget.`,`“Keep learning” starts up to ${RULES.round} questions with your species selection and answer method, ignoring custom question-count and progress filters. Under “Build another round yourself”, choose those settings yourself. Both allow new targets beyond the daily limit; their introductions also count towards the daily budget used.`)],
 ['formats',c('So kannst du antworten','Ways to answer'),c('Bei „Erst überlegen“ erinnerst du dich zuerst und forderst dann die Auswahl an; bei direkter Auswahl ist sie sofort sichtbar. Beide üben das Wiedererkennen und teilen denselben Lernstand. Texteingabe übt freien Abruf, Karteikarten nutzen Selbsteinschätzung. „Weiß ich nicht“ zeigt die Lösung.','With “Think first”, try to recall before requesting the options; direct choice shows them immediately. Both practise recognition and share progress. Typing practises recall; flashcards use self-assessment. “I don’t know” reveals the answer.')+ref(4)+ref(5)],
 ['feedback',c('Aus Fehlern lernen','Learning from mistakes'),c('Korrekturfeedback kann richtige Antworten stärken und das Übernehmen falscher Auswahlantworten verringern.','Corrective feedback can strengthen correct answers and reduce learning of incorrect options.')+ref(3)+`</p><p>`+c(`Nach jeder Antwort siehst du die Lösung. Fehler oder richtige Antworten mit Hinweis führen zu bis zu ${RULES.maxRetries} Zusatzversuchen, möglichst nach drei anderen Fragen. Ohne mögliche Zwischenfrage entfällt der Zusatzversuch. Zusatzversuche und Hinweise fügen keine zeitversetzte Bestätigung hinzu; Hinweise erhalten bisherige Bestätigungen.`,`You see the solution after every answer. Errors or correct answers with a hint can lead to up to ${RULES.maxRetries} extra attempts, preferably after three other questions. No extra attempt is added without an intervening question. Extra attempts and hints add no spaced confirmation; hints preserve existing confirmations.`)],
 ['progress',c('Was dein Lernstand bedeutet','What your progress means'),c('Erfolgreiches Abrufen in getrennten Sitzungen unterstützt das Behalten.','Successful retrieval across spaced sessions supports retention.')+ref(1)+ref(2)+`</p><p>`+c(`„Fällig“ heißt: Es ist Zeit für eine Wiederholung. Nach einer ersten erfolgreichen Übung ohne Hinweis brauchst du für „sicher“ ${RULES.confirmations} richtige, fällige Wiederholungen ohne Hinweis, jeweils mindestens ${RULES.minGap/3600000} Stunden nach dem letzten bewerteten Versuch. Fehler setzen die Bestätigungsserie zurück. Auch sichere Ziele werden wieder fällig.`,`“Due” means it is time for a review. After an initial successful practice without hints, “secure” requires ${RULES.confirmations} correct due reviews without hints, each at least ${RULES.minGap/3600000} hours after the last graded attempt. Errors reset the confirmation sequence. Secure targets become due again too.`)+`</p><p>`+c('Der Lernstand wird je Art, Ausgangssprache, gesuchtem Namen oder Code und Methodenfamilie erfasst: „Sicher wiedererkannt“, „Sicher abgerufen“ oder „Nach eigener Einschätzung sicher“. Ein Methodenwechsel überträgt daher sicheres Wiedererkennen nicht auf freien Abruf. Frühere Lernwerte bleiben erhalten; ehemals „beherrschte“ Ziele werden neu bestätigt.','Progress is tracked by species, question language, target name or code and method family: “Securely recognised”, “Securely recalled” or “Secure by self-assessment”. Switching methods does not transfer secure recognition to recall. Earlier progress is retained; previously “mastered” targets need new confirmations.')+`</p><p>`+c(`Nach der ersten richtigen Übung ohne Hinweis ist die Wiederholung nach 24 Stunden fällig. Die Abstände wachsen über ${RULES.intervals.join(', ')} Tage. Fehler verkürzen die Stufe und machen die Wiederholung nach zehn Minuten fällig; Hinweise setzen sie auf spätestens 24 Stunden später, erhalten aber frühere Termine.`,`After the first correct practice without hints, review is due in 24 hours. Intervals grow through ${RULES.intervals.join(', ')} days. Errors reduce the stage and make review due in ten minutes; hints schedule it within 24 hours while retaining earlier dates.`)+`</p><p>`+c('Richtige vorzeitige Übungen ohne Hinweis und richtige Zusatzversuche lassen Termine unverändert und fügen keine Bestätigung hinzu. Eine richtige fällige Antwort ohne Hinweis im ersten Versuch mit weniger als 24 Stunden Abstand setzt den Termin auf 24 Stunden später, ohne Bestätigung. Auch freiwilliges Üben kann Bestätigungen liefern, wenn Termin und Abstand passen; Fehler und Hinweise wirken wie oben beschrieben.','Correct early practice without hints and correct extra attempts leave dates unchanged and add no confirmation. A correct, unhinted first attempt on a due question less than 24 hours after the last graded attempt schedules review 24 hours later, without confirmation. Optional practice can earn confirmations when the review is due and the gap sufficient; errors and hints have the effects described above.')],
 ['research',c('Warum mit Abstand wiederholen?','Why space out reviews?'),c('Studien stützen aktives Abrufen, Korrekturfeedback und verteiltes Lernen als Lernprinzipien.','Studies support retrieval practice, corrective feedback and spaced learning as learning principles.')+ref(0)+ref(6)+`</p><p>`+c('Rundengröße, Tagesbudget, Mindestabstand, Bestätigungen, Zusatzversuche und Intervallfolge sind App-Festlegungen: keine in diesen Studien validierten Schwellen und kein wissenschaftlich ermitteltes Optimum. „Sicher“ ist eine Fortschrittsanzeige, keine Garantie dauerhaften Behaltens. Untersucht wurden Lernprinzipien, nicht BirdNames DE; auch „Erst überlegen“ garantiert keine besseren Ergebnisse.','Round size, daily budget, minimum gap, confirmations, extra attempts and intervals are app choices: not thresholds validated by these studies and not a scientifically established optimum. “Secure” is a progress label, not guaranteed lasting retention. The research tested learning principles, not BirdNames DE; “Think first” does not guarantee better results either.')]
 ];
 return `<h1>${c('Lernmethode','Learning method')}</h1><div class="panel information-page"><p class="intro">${c('Namen kennenlernen, selbst erinnern, Rückmeldung bekommen und mit Abstand wiederholen.','Learn names, try to remember, get feedback and review after a delay.')}</p><p class="muted">${c('App-Verhalten geprüft am','App behavior reviewed on')} ${date(METHOD_CONTENT_REVIEWED)}. ${c('Quellen geprüft am','Sources reviewed on')} ${date(METHOD_REVIEWED)}.</p>${sections.map(([id,title,body])=>`<section aria-labelledby="method-${id}"><h2 id="method-${id}">${title}</h2><p>${body}</p></section>`).join('')}<section aria-labelledby="method-sources"><h2 id="method-sources">${c('Wissenschaftliche Quellen','Scientific sources')}</h2><ol>${METHOD_SOURCES.map(([authors,title,url,de,en,doi],i)=>`<li id="method-source-${i+1}" tabindex="-1"><a href="${url}" target="_blank" rel="noopener noreferrer">${esc(authors)}: <cite>${esc(title)}</cite> ↗</a><p>${esc(english?en:de)}</p>${doi?`<p><a href="${esc(doi)}" target="_blank" rel="noopener noreferrer">DOI ↗</a></p>`:''}</li>`).join('')}</ol></section><a class="button-link" href="#lernen">${c('Zurück zum Lernen','Back to learning')}</a></div>`;
}
